create table public.secondary_staff_details(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,staff_profile_id uuid not null unique references public.staff_profiles(id) on delete cascade,photo_path text,department text,subject_specialisations text[] not null default '{}',emergency_contact_name text,emergency_contact_relationship text,emergency_contact_phone text,address text,national_id text,created_by uuid not null references auth.users(id),updated_at timestamptz not null default now());
create table public.secondary_staff_qualifications(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,staff_profile_id uuid not null references public.staff_profiles(id) on delete cascade,qualification_title text not null,institution text,field_of_study text,qualification_level text not null default 'other',award_date date,certificate_reference text,verification_status text not null default 'pending' check(verification_status in('pending','verified','rejected')),verification_notes text,created_at timestamptz not null default now(),created_by uuid not null references auth.users(id));
create table public.secondary_staff_documents(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,staff_profile_id uuid not null references public.staff_profiles(id) on delete cascade,document_type text not null,file_name text not null,file_path text not null,mime_type text,file_size bigint,issue_date date,expiry_date date,created_at timestamptz not null default now(),created_by uuid not null references auth.users(id));
create table public.secondary_staff_employment_history(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,staff_profile_id uuid not null references public.staff_profiles(id) on delete cascade,event_type text not null check(event_type in('transfer','promotion','resignation','retirement','contract_end','termination','reinstatement','other')),effective_date date not null,from_department text,to_department text,from_title text,to_title text,reason text,notes text,created_at timestamptz not null default now(),created_by uuid not null references auth.users(id));
create table public.secondary_staff_responsibilities(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,staff_profile_id uuid not null references public.staff_profiles(id) on delete cascade,responsibility_type text not null check(responsibility_type in('class_teacher','department_head','substitute','duty','club','other')),title text not null,class_id uuid,subject_id uuid,start_date date,end_date date,notes text,is_active boolean not null default true,created_at timestamptz not null default now(),created_by uuid not null references auth.users(id));
create table public.secondary_staff_leave_requests(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,staff_profile_id uuid not null references public.staff_profiles(id) on delete cascade,leave_type text not null,start_date date not null,end_date date not null,reason text not null,status text not null default 'pending' check(status in('pending','approved','rejected','cancelled')),review_notes text,reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now(),created_by uuid not null references auth.users(id),check(end_date>=start_date));
create table public.secondary_staff_reviews(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,staff_profile_id uuid not null references public.staff_profiles(id) on delete cascade,review_date date not null,review_period text,reviewer_membership_id uuid references public.school_memberships(id),rating numeric(3,1) check(rating between 0 and 5),strengths text,improvement_areas text,goals text,confidential_notes text,created_at timestamptz not null default now(),created_by uuid not null references auth.users(id));
create table public.secondary_staff_disciplinary_records(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,staff_profile_id uuid not null references public.staff_profiles(id) on delete cascade,incident_date date not null,category text not null,description text not null,action_taken text,outcome text,status text not null default 'open' check(status in('open','under_review','resolved','closed')),confidential boolean not null default true,created_at timestamptz not null default now(),created_by uuid not null references auth.users(id));
create table public.secondary_staff_module_settings(school_id uuid primary key references public.schools(id) on delete cascade,payroll_enabled boolean not null default false,updated_at timestamptz not null default now(),updated_by uuid references auth.users(id),created_by uuid not null references auth.users(id));
create table public.secondary_staff_payroll(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,staff_profile_id uuid not null references public.staff_profiles(id) on delete cascade,pay_period text not null,base_salary numeric(12,2) not null default 0 check(base_salary>=0),allowances numeric(12,2) not null default 0 check(allowances>=0),deductions numeric(12,2) not null default 0 check(deductions>=0),currency text not null default 'MWK',status text not null default 'draft' check(status in('draft','approved','paid')),payment_date date,reference text,notes text,created_at timestamptz not null default now(),created_by uuid not null references auth.users(id),unique(staff_profile_id,pay_period));
create index secondary_staff_qualifications_idx on public.secondary_staff_qualifications(school_id,staff_profile_id);
create index secondary_staff_documents_idx on public.secondary_staff_documents(school_id,staff_profile_id);
create index secondary_staff_history_idx on public.secondary_staff_employment_history(school_id,staff_profile_id,effective_date desc);
create index secondary_staff_responsibilities_idx on public.secondary_staff_responsibilities(school_id,staff_profile_id,is_active);
create index secondary_staff_leave_idx on public.secondary_staff_leave_requests(school_id,status,start_date);
create index secondary_staff_reviews_idx on public.secondary_staff_reviews(school_id,staff_profile_id,review_date desc);
create index secondary_staff_discipline_idx on public.secondary_staff_disciplinary_records(school_id,staff_profile_id,incident_date desc);
create index secondary_staff_payroll_idx on public.secondary_staff_payroll(school_id,pay_period);
do $$ declare t text; begin foreach t in array array['secondary_staff_details','secondary_staff_qualifications','secondary_staff_documents','secondary_staff_employment_history','secondary_staff_responsibilities','secondary_staff_leave_requests','secondary_staff_reviews','secondary_staff_disciplinary_records','secondary_staff_module_settings','secondary_staff_payroll'] loop
execute format('alter table public.%I enable row level security',t); execute format('alter table public.%I force row level security',t); execute format('grant select,insert,update,delete on public.%I to authenticated',t);
execute format('create policy %I on public.%I for select to authenticated using(exists(select 1 from public.school_memberships m where m.school_id=%I.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in (''owner'',''school_admin'',''headteacher'',''deputy_headteacher'',''bursar'')))',t||'_read',t,t);
execute format('create policy %I on public.%I for insert to authenticated with check(created_by=(select auth.uid()) and exists(select 1 from public.school_memberships m where m.school_id=%I.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in (''owner'',''school_admin'',''headteacher'',''deputy_headteacher'',''bursar'')))',t||'_insert',t,t);
execute format('create policy %I on public.%I for update to authenticated using(exists(select 1 from public.school_memberships m where m.school_id=%I.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in (''owner'',''school_admin'',''headteacher'',''deputy_headteacher'',''bursar''))) with check(exists(select 1 from public.school_memberships m where m.school_id=%I.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in (''owner'',''school_admin'',''headteacher'',''deputy_headteacher'',''bursar'')))',t||'_update',t,t,t);
execute format('create policy %I on public.%I for delete to authenticated using(exists(select 1 from public.school_memberships m where m.school_id=%I.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in (''owner'',''school_admin'',''headteacher'')))',t||'_delete',t,t);
end loop; end $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('conedu-staff-files','conedu-staff-files',false,15728640,array['image/jpeg','image/png','application/pdf']) on conflict(id) do update set public=false,file_size_limit=15728640,allowed_mime_types=array['image/jpeg','image/png','application/pdf'];
create policy conedu_staff_files_read on storage.objects for select to authenticated using(bucket_id='conedu-staff-files' and exists(select 1 from public.school_memberships m where m.school_id=((storage.foldername(name))[1])::uuid and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','headteacher','deputy_headteacher','bursar')));
create policy conedu_staff_files_insert on storage.objects for insert to authenticated with check(bucket_id='conedu-staff-files' and exists(select 1 from public.school_memberships m where m.school_id=((storage.foldername(name))[1])::uuid and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','headteacher')));
create policy conedu_staff_files_delete on storage.objects for delete to authenticated using(bucket_id='conedu-staff-files' and exists(select 1 from public.school_memberships m where m.school_id=((storage.foldername(name))[1])::uuid and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','headteacher')));